\mathsf{Ax}_{Len}^{508}
=
\{S(t)=0\to\bot:t\in\mathsf{Tm}_{508}^{\mathsf N}\}
\cup
\{S(t)=S(u)\to t=u:t,u\in\mathsf{Tm}_{508}^{\mathsf N}\}
\cup
\{\ell(\langle\rangle)=0\}
\cup
\{\ell(\operatorname{cat}(p,n))=S(\ell(p)):
p\in\mathsf{Tm}_{508}^{\mathsf Fin},\ n\in\mathsf{Tm}_{508}^{\mathsf N}\}.

\mathsf{Ax}_{Pref}^{508}
=
\left\{
\operatorname{Pref}(s,\alpha)\leftrightarrow
\forall i\bigl(\operatorname{Le}(S(i),\ell(s))\to
\operatorname{nth}(s,i)=\operatorname{bit}(\alpha,i)\bigr):
\begin{array}{l}
s\in\mathsf{Tm}_{508}^{\mathsf Fin},\ \alpha\in\mathsf{Tm}_{508}^{\mathsf Bin},\\
i\in\mathsf{Var}_{508}^{\mathsf N},\ i\notin\operatorname{FVt}_{508}(s)\cup\operatorname{FVt}_{508}(\alpha)
\end{array}
\right\}.
